-- Finance F7-A (docs/finance-catalog-f7a.md): the products and services catalog. Generated by
-- `prisma migrate diff`, then the constraints, guard, index, grants and RLS Prisma cannot express were
-- added by hand (section marked "hand-written"). Wrapped in one transaction (docs/migration-readiness.md
-- §7, STAB-M6).
--
-- Ordering: depends on 20261115000000_finance (finance_tax_rates, the FN017 archived_reference code).
-- It changes no existing table, column or row; it adds one table. It does not touch quotes, invoices,
-- credit notes, their lines, payments, reminders or recurring billing. It sorts after Scheduling S2
-- (20261128000000_scheduling_resources) and Communications E1 (20261129000000_communications_erasure)
-- and depends on neither. No privileged SQL.
--
-- SQLSTATEs (class FN, finance): FN050 item identity or type fixed, FN051 an archived item is read-only
-- (only a restore may change it) or an archive changed other fields, FN052 version must advance by one.
-- A newly linked archived tax rate raises the existing FN017 (archived_reference).
BEGIN;
-- CreateTable
CREATE TABLE "finance_catalog_items" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "type" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "description" TEXT,
    "code" TEXT,
    "unit" TEXT NOT NULL,
    "unit_price" DECIMAL(18,6),
    "currency_code" CHAR(3) NOT NULL,
    "tax_mode" TEXT NOT NULL,
    "tax_rate_id" UUID,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE',
    "archived_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_by_id" UUID,
    "updated_by_id" UUID,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "finance_catalog_items_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "finance_catalog_items_business_id_archived_at_status_name_i_idx" ON "finance_catalog_items"("business_id", "archived_at", "status", "name", "id");

-- CreateIndex
CREATE INDEX "finance_catalog_items_business_id_tax_rate_id_idx" ON "finance_catalog_items"("business_id", "tax_rate_id");

-- CreateIndex
CREATE UNIQUE INDEX "finance_catalog_items_business_id_id_key" ON "finance_catalog_items"("business_id", "id");

-- AddForeignKey
ALTER TABLE "finance_catalog_items" ADD CONSTRAINT "finance_catalog_items_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "finance_catalog_items" ADD CONSTRAINT "finance_catalog_items_tax_rate_fkey" FOREIGN KEY ("business_id", "tax_rate_id") REFERENCES "finance_tax_rates"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- ---------------------------------------------------------------------------------------------
-- hand-written: constraints, code uniqueness, guard, least privilege and RLS.

ALTER TABLE "finance_catalog_items"
  ADD CONSTRAINT finance_catalog_items_type CHECK ("type" IN ('PRODUCT', 'SERVICE')),
  ADD CONSTRAINT finance_catalog_items_status CHECK ("status" IN ('ACTIVE', 'INACTIVE')),
  ADD CONSTRAINT finance_catalog_items_name_length CHECK (char_length(btrim("name")) BETWEEN 1 AND 200 AND char_length("name") <= 200),
  ADD CONSTRAINT finance_catalog_items_description_length CHECK ("description" IS NULL OR char_length("description") <= 2000),
  -- A code is stored trimmed, 1 to 64 characters, with no control characters.
  ADD CONSTRAINT finance_catalog_items_code_shape CHECK ("code" IS NULL OR ("code" = btrim("code") AND char_length("code") BETWEEN 1 AND 64 AND "code" !~ '[[:cntrl:]]')),
  ADD CONSTRAINT finance_catalog_items_unit_shape CHECK ("unit" ~ '^[a-z][a-z0-9_]{0,19}$'),
  ADD CONSTRAINT finance_catalog_items_unit_price CHECK ("unit_price" IS NULL OR "unit_price" >= 0),
  ADD CONSTRAINT finance_catalog_items_currency CHECK ("currency_code" ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT finance_catalog_items_tax_mode CHECK ("tax_mode" IN ('BUSINESS_DEFAULT', 'RATE', 'NONE')),
  ADD CONSTRAINT finance_catalog_items_tax_rate CHECK (("tax_mode" = 'RATE') = ("tax_rate_id" IS NOT NULL)),
  ADD CONSTRAINT finance_catalog_items_version_positive CHECK ("version" >= 1);

-- One item per code per business, ignoring case. Archived items keep their code, so a code is never
-- reused for a different item (future stock and purchasing records can rely on it).
CREATE UNIQUE INDEX "finance_catalog_items_code_key" ON "finance_catalog_items" ("business_id", lower("code")) WHERE "code" IS NOT NULL;

-- The guard: identity and type fixed; times stamped by the database; the version advances by exactly
-- one on every update; an archived item is read-only except for its restore; an archive changes nothing
-- else; a newly linked tax rate must be active. The rate is read FOR SHARE, so a concurrent archive of
-- that rate either commits first (and the link is refused) or waits for this unit of work.
CREATE FUNCTION finance_catalog_items_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  rate_archived timestamptz;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.archived_at IS NOT NULL OR NEW.version <> 1 THEN
      RAISE EXCEPTION 'a catalog item is created active and unarchived at version 1' USING ERRCODE = 'FN050';
    END IF;
    NEW.created_at := now();
  ELSE
    IF NEW.id <> OLD.id OR NEW.business_id <> OLD.business_id OR NEW.type <> OLD.type OR NEW.created_at <> OLD.created_at
       OR NEW.created_by_id IS DISTINCT FROM OLD.created_by_id THEN
      RAISE EXCEPTION 'a catalog item''s identity and type are fixed' USING ERRCODE = 'FN050';
    END IF;
    IF NEW.version <> OLD.version + 1 THEN
      RAISE EXCEPTION 'a catalog item''s version advances by one on every change' USING ERRCODE = 'FN052';
    END IF;
    IF (NEW.name, NEW.description, NEW.code, NEW.unit, NEW.unit_price, NEW.currency_code, NEW.tax_mode, NEW.tax_rate_id, NEW.status)
       IS DISTINCT FROM (OLD.name, OLD.description, OLD.code, OLD.unit, OLD.unit_price, OLD.currency_code, OLD.tax_mode, OLD.tax_rate_id, OLD.status)
       AND (OLD.archived_at IS NOT NULL OR NEW.archived_at IS NOT NULL) THEN
      RAISE EXCEPTION 'an archived catalog item is read-only, and archiving changes nothing else' USING ERRCODE = 'FN051';
    END IF;
    IF OLD.archived_at IS NOT NULL AND NEW.archived_at IS NOT NULL THEN
      RAISE EXCEPTION 'an archived catalog item is read-only' USING ERRCODE = 'FN051';
    END IF;
    IF OLD.archived_at IS NULL AND NEW.archived_at IS NOT NULL THEN
      NEW.archived_at := now();
    END IF;
  END IF;
  IF NEW.tax_rate_id IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.tax_rate_id IS DISTINCT FROM OLD.tax_rate_id) THEN
    SELECT r.archived_at INTO rate_archived FROM public.finance_tax_rates r
     WHERE r.business_id = NEW.business_id AND r.id = NEW.tax_rate_id FOR SHARE;
    -- A missing rate (or another business's, invisible under RLS) is left to the composite FK (23503).
    IF FOUND AND rate_archived IS NOT NULL THEN
      RAISE EXCEPTION 'an archived tax rate cannot be newly linked' USING ERRCODE = 'FN017';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;
CREATE TRIGGER finance_catalog_items_guard BEFORE INSERT OR UPDATE ON "finance_catalog_items"
  FOR EACH ROW EXECUTE FUNCTION finance_catalog_items_guard();
REVOKE ALL ON FUNCTION finance_catalog_items_guard() FROM PUBLIC;

-- ---- least privilege ---------------------------------------------------------------------------
-- No DELETE: items are deactivated or archived and keep their history. Identity, type and creation
-- columns are not updatable at all; the guard holds the rest.
REVOKE ALL ON "finance_catalog_items" FROM bos_app;
GRANT SELECT, INSERT ON "finance_catalog_items" TO bos_app;
GRANT UPDATE ("name", "description", "code", "unit", "unit_price", "currency_code", "tax_mode", "tax_rate_id", "status", "archived_at",
              "version", "updated_by_id", "updated_at")
  ON "finance_catalog_items" TO bos_app;

-- ---- row-level security --------------------------------------------------------------------------
ALTER TABLE "finance_catalog_items" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "finance_catalog_items" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "finance_catalog_items" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

COMMIT;
